#!/usr/bin/env python3
"""sen0401_lineage_cancel_ch11page v1_0_0 - closes ST_Ch11_Page_R24 (the chapter 11 page 9.79.0) with its Build (Suspended) and Verify (Proposed) tasks as CANCELLED, superseded by ST_Ch11_PageRebuild (controlled Done in v0.515.0). The owner's rule on cancelling is applied: an as-is fit-gap and impact analysis (accomplished, failed, in progress, due; an ImpactAssessment) and a closure report marked CANCELLED (a ClosureReport) are recorded in the SAME version as the cancellation, before it. Criteria are not edited, not waived. Usage: no arguments; one new register version."""
__version__ = "1.0.0"
import os, re, sys, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0401_lineage_succession_v1_1_0 as M
import sen0401_lineage_succession3_v1_1_0 as X
import sen0401_lineage_template_revision_v1_0_0 as T
import sen0401_lineage_control_v1_0_0 as C
lit = C.lit
src = M.newest(); t = open(src, encoding="utf-8").read(); nxt, cur = M.next_version(src); L = []; now = M.now()
_i, _j = T.blk(t, "TK_Ch11_PageRebuild_Verify"); assert "hasState backlog:Done" in t[_i:_j]
FITGAP = ("AS-IS FIT-GAP AND IMPACT ANALYSIS of ex:ST_Ch11_Page_R24 (read from the register v%s and the control of 2026-10-26; criterion AC9_Page_Ch11). "
          "ACCOMPLISHED (met, measured by the control): the page 9.79.0 exists as a new file (commit 95b5833) with its inputs (commit 8cfc35e: lecture export, resources, pywheels, Pyodide preflight of the 17 examples, 0 failures); charset check; chapter-code manifest equals the page tab (17 examples); every hyperlink of the newest deck carried (15 of 15); story layout probe 12 of 12; deck match 0 not carried; Research and Deck chapter checks. "
          "FAILED (measured, recorded in the control of v0.497.0): the page tests 9.37.0, 9.34.1 and 9.35.1 (exit 1 each in the control's own runs, TimeoutError in the ERD step: the sections ERD of the template 9.52.4 draws HeaderFields over the centre of BlockContainer); the Page chapter check; the page ABox and the stored result (never made). The cause is in the template, not in the page data (change request ex:CR3_TemplateErd). "
          "IN PROGRESS: nothing; the Build task is Suspended since the control and its Verify task was never started. "
          "DUE: nothing on this unit: what it was to deliver (a chapter 11 page that meets AC9_Page_Ch11's measures) is delivered by ex:ST_Ch11_PageRebuild, whose criterion AC9_PageRebuild_Ch11 repeats those measures and adds the ERD collision probe, controlled MET on the page 9.80.0 (v0.515.0). "
          "IMPACT of the cancellation: the page file 9.79.0 and its commits stay in the repository, unchanged (nothing is deleted or edited); the criterion AC9_Page_Ch11 is not edited and not waived: it stays on the register as the criterion this unit did not meet, and the same measures are met by AC9_PageRebuild_Ch11; no other item depends on these three (checked: the only dependency is the Verify task on its own Build task); the open-story ranking loses one entry (0.16) and no other score changes; the mission's coverage is unaffected (the chapter 11 page is delivered by the rebuild).")
for tk in ("TK_Ch11_Page_Verify_R24", "TK_Ch11_Page_Build_R24", "ST_Ch11_Page_R24"):
    i, j = T.blk(t, tk); b = t[i:j]; m = re.search(r"backlog:hasState backlog:(Proposed|Ready|InProgress|Suspended)\b", b); assert m, tk
L.append('\nex:IA3_Ch11PageCancel a backlog:ImpactAssessment ;\n    rdfs:label "As-is fit-gap and impact of cancelling the chapter 11 page 9.79.0 story"@en ;\n    backlog:analyzesRequest ex:CR3_TemplateErd ; backlog:identifiesAffectedLineage ex:Lineage3 ;\n    backlog:hasImpactStatement %s .\n' % lit(FITGAP % cur))
L.append('\nex:ClosureRep3_Ch11PageR24 a backlog:ClosureReport ;\n    rdfs:label "Closure report of the chapter 11 page 9.79.0 story: CANCELLED (superseded)"@en ; backlog:belongsToLineage ex:Lineage3 ;\n    backlog:reportGeneratedAt "%s"^^xsd:dateTime ; rdfs:seeAlso ex:ST_Ch11_Page_R24, ex:IA3_Ch11PageCancel, ex:ST_Ch11_PageRebuild ;\n    backlog:hasClosureSummary %s .\n' % (now, lit("CLOSURE STATUS: CANCELLED (not Done, not failed-and-forgotten). The story ex:ST_Ch11_Page_R24 with its tasks TK_Ch11_Page_Build_R24 (was Suspended) and TK_Ch11_Page_Verify_R24 (was Proposed) is cancelled on " + now + " UTC because its deliverable was superseded by ex:ST_Ch11_PageRebuild (the chapter 11 page 9.80.0 on the template 9.52.5, controlled Done). The unit itself did not meet its criterion (page tests failed, see the analysis ex:IA3_Ch11PageCancel); that is kept as the record and is not waived. The failed page stays in the repository unchanged. Lesson: a template defect (the sections ERD) can fail a page that is otherwise correct; the ERD collision probe is now a measure of the rebuilt page and of the pages of chapters 12 to 14.")))
for tk in ("TK_Ch11_Page_Verify_R24", "TK_Ch11_Page_Build_R24", "ST_Ch11_Page_R24"):
    i, j = T.blk(t, tk); b = t[i:j]; m = re.search(r"backlog:hasState backlog:(Proposed|Ready|InProgress|Suspended)\b", b); frm = m.group(1)
    why = "Cancelled %s UTC (v%s): superseded by ex:ST_Ch11_PageRebuild (controlled Done); the unit's own criterion was not met (page tests failed, see ex:IA3_Ch11PageCancel and ex:ClosureRep3_Ch11PageR24, status CANCELLED). Criteria not edited, not waived." % (now, nxt)
    nb = b.replace(m.group(0), "backlog:hasState backlog:Cancelled", 1)
    nb = re.sub(r'backlog:hasRationale "(?:[^"\\]|\\.)*"', lambda _: "backlog:hasRationale " + lit(why), nb, count=1) if "backlog:hasRationale" in nb else nb.replace("backlog:hasState backlog:Cancelled", "backlog:hasState backlog:Cancelled ; backlog:hasRationale " + lit(why), 1)
    nb = re.sub(r'backlog:lastAuditedAt "[^"]*"', 'backlog:lastAuditedAt "%s"' % now, nb, count=1) if "lastAuditedAt" in nb else nb
    t = t[:i] + nb + t[j:]; time.sleep(1.1); at = M.now(); L.append(C.transition("Cx11p_" + tk, tk, "T_Withdraw" + frm, at, why, tk + " cancelled"))
print(os.path.basename(M.write_new(src, X.set_status(t + "\n" + "".join(L), "LS_InProgress"), nxt, cur, "ST_Ch11_Page_R24 and its tasks cancelled (superseded by ST_Ch11_PageRebuild) with an as-is fit-gap and impact analysis and a closure report marked CANCELLED.")))
